(()=>{'use strict';const $=(q)=>document.querySelector(q),$$=(q)=>[...document.querySelectorAll(q)];const page=document.body.dataset.page;
const menu=$('.menu-toggle'),nav=$('#inner-nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.toggleAttribute('data-open',open);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.hasAttribute('data-open')){nav.removeAttribute('data-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.focus();}});
const prices=[29,49,65,79],storageKey='phonebridger.setup.v1';const readSetup=()=>{try{const value=JSON.parse(localStorage.getItem(storageKey));return value&&Number.isInteger(value.holders)&&value.holders>=0&&value.holders<=3&&['black','silver'].includes(value.finish)?value:null;}catch(_){return null;}};
if(page==='shop'){
 const inputs=$$('input[name=setup]'),finishes=$$('input[name=finish]');const params=new URLSearchParams(location.search);const saved=readSetup();const count=params.has('holders')?Number(params.get('holders')):saved?.holders;const finish=params.get('finish')||saved?.finish;
 if(Number.isInteger(count)&&count>=0&&count<=3)inputs[count].checked=true;if(['black','silver'].includes(finish))finishes.find(i=>i.value===finish).checked=true;
 function current(){return {holders:Number($('input[name=setup]:checked').value),finish:$('input[name=finish]:checked').value};}
 function render(){const s=current();$('.product-stage').dataset.count=s.holders;$('.finish-options').hidden=!s.holders;$('[data-total]').textContent='$'+prices[s.holders];const inclusion=$('[data-holder-inclusion]');inclusion.hidden=!s.holders;inclusion.lastChild.textContent=`${s.holders} magnetic holder${s.holders===1?'':'s'} · ${s.finish==='black'?'Black':'Silver'}`;$$('[data-holder]').forEach((img,i)=>{img.hidden=i>=s.holders;img.src=`../assets/closing-conversion-v1/holder-${s.finish}-640.webp`;});$('[data-interest]').href=`../contact/?topic=setup&holders=${s.holders}&finish=${s.finish}`;$('[data-setup-status]').textContent='';}
 [...inputs,...finishes].forEach(input=>input.addEventListener('change',render));$('[data-save-setup]').addEventListener('click',()=>{const s=current();try{localStorage.setItem(storageKey,JSON.stringify(s));$('[data-setup-status]').textContent='Saved in this browser. Your choice is ready when you come back.';}catch(_){$('[data-setup-status]').textContent='This browser could not save your choice. You can still ask about this setup.';}});render();
}
if(page==='contact'){
 const params=new URLSearchParams(location.search),topic=params.get('topic');if($$('#topic option').some(o=>o.value===topic))$('#topic').value=topic;
 const count=Number(params.get('holders'));const finish=params.get('finish');if(params.has('holders')&&Number.isInteger(count)&&count>=0&&count<=3&&['black','silver'].includes(finish))$('#message').value=`I’m interested in ${count?`App + ${count} holder${count===1?'':'s'} in ${finish}`:'App only'} (planned USD price $${prices[count]}).\n\nMy phone / laptop setup: `;
 $('[data-contact]').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const category=$('#topic option:checked').textContent;const email=$('#contact-email').value.trim();const message=$('#message').value.trim();const draft=`mailto:hello@phonebridger.com?subject=${encodeURIComponent('PhoneBridger — '+category)}&body=${encodeURIComponent(message+(email?'\n\nReply email: '+email:''))}`;const link=$('[data-email-draft]');link.href=draft;link.hidden=false;$('[data-contact-status]').textContent='Your draft is ready. Open it below and send it from your email app.';link.focus();});
}
$$('[data-show-password]').forEach(button=>button.addEventListener('click',()=>{const input=$('#password'),visible=input.type==='password';input.type=visible?'text':'password';button.setAttribute('aria-pressed',String(visible));button.setAttribute('aria-label',visible?'Hide password':'Show password');}));
const endpoint=action=>new URL('../api/account/'+action,location.href);async function api(action,body){const response=await fetch(endpoint(action),{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,credentials:'same-origin'});let data;try{data=await response.json();}catch(_){throw Error('Account service is not connected in this preview. Please use the local account preview or contact support.');}if(!response.ok)throw Error(data.error||'Please try again.');return data;}
if(page==='login'||page==='register'){$('[data-auth]').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const button=form.querySelector('[type=submit]'),status=$('[data-auth-status]');button.disabled=true;form.setAttribute('aria-busy','true');status.textContent=page==='register'?'Creating your local preview account…':'Signing in…';try{await api(page,{email:$('#email').value,password:$('#password').value});location.assign('../account/');}catch(error){status.textContent=error.message;status.tabIndex=-1;status.focus();}finally{button.disabled=false;form.removeAttribute('aria-busy');}});}
if(page==='account'){
 const saved=readSetup();if(saved)$('[data-saved-summary]').textContent=saved.holders?`App + ${saved.holders} holder${saved.holders===1?'':'s'} · ${saved.finish==='black'?'Black':'Silver'} · Planned price $${prices[saved.holders]}`:'App only · Planned price $29';
 api('session').then(({user})=>{if(!user){location.replace('../login/');return;}$('[data-account-email]').textContent=user.email;$('[data-account-status]').textContent='You’re signed in to the local preview.';$('[data-logout]').hidden=false;}).catch(error=>{$('[data-account-status]').textContent=error.message;});
 $('[data-logout]').addEventListener('click',async e=>{e.currentTarget.disabled=true;try{await api('logout',{});location.replace('../login/');}catch(error){$('[data-account-status]').textContent=error.message;e.currentTarget.disabled=false;}});
}
})();
